def histogram(test):
    if not test.strip():
        return {}
    counts = {}
    for char in test.split():
        counts[char] = counts.get(char, 0) + 1
    max_count = max(counts.values())
    return {k: v for k, v in counts.items() if v == max_count}

def maximum(arr, k):
    if k == 0:
        return []
    return sorted(arr)[-k:]

def greatest_common_divisor(a: int, b: int) -> int:
    """ Return a greatest common divisor of two integers a and b
    >>> greatest_common_divisor(3, 5)
    1
    >>> greatest_common_divisor(25, 15)
    5
    """
    while b:
        a, b = b, a % b
    return abs(a)

def digits(n):
    product = 1
    has_odd = False
    for d in str(n):
        digit = int(d)
        if digit % 2 != 0:
            product *= digit
            has_odd = True
    return product if has_odd else 0

def words_in_sentence(sentence):
    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True
    return " ".join(word for word in sentence.split() if is_prime(len(word)))

def do_algebra(operator, operand):
    expr = str(operand[0])
    for op, val in zip(operator, operand[1:]):
        expr += f" {op} {val}"
    return eval(expr)

def unique(l: list):
    """Return sorted unique elements in a list
    >>> unique([5, 3, 5, 2, 3, 3, 9, 0, 123])
    [0, 2, 3, 5, 9, 123]
    """
    return sorted(set(l))

def change_base(x: int, base: int):
    if x == 0:
        return '0'
    digits = []
    while x > 0:
        digits.append(str(x % base))
        x //= base
    return ''.join(reversed(digits))

def decode_shift(s: str):
    """
    takes as input string encoded with encode_shift function. Returns decoded string.
    """
    return "".join([chr(((ord(ch) - 5 - ord("a")) % 26) + ord("a")) for ch in s])

def fruit_distribution(s, n):
    import re
    nums = re.findall(r'\d+', s)
    return n - int(nums[0]) - int(nums[1])

def triangle_area(a, b, c):
    if a + b <= c or a + c <= b or b + c <= a:
        return -1
    s = (a + b + c) / 2
    area = (s * (s - a) * (s - b) * (s - c)) ** 0.5
    return round(area, 2)

def prime_length(string):
    n = len(string)
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

def check_dict_case(dict):
    if not dict:
        return False
    return all(isinstance(k, str) and k.islower() for k in dict) or all(isinstance(k, str) and k.isupper() for k in dict)

def closest_integer(value):
    num = float(value)
    return int(num + 0.5) if num >= 0 else int(num - 0.5)
